{"cmd":"python - <<'PY'
import pandas as pd
import numpy as np
import re

input_path = '/root/environment/data/ckd_lab_data.csv'
ref_path = '/root/.codex/skills/lab-unit-harmonization/reference/ckd_lab_features.md'
output_path = '/root/ckd_lab_data_harmonized.csv'

# Load data
raw_df = pd.read_csv(input_path)

# Parse reference ranges
ranges = {}
for line in open(ref_path):
    line = line.strip()
    if not line.startswith('|') or '---' in line:
        continue
    parts = [p.strip() for p in line.strip('|').split('|')]
    if not parts or parts[0] in ('Key', ''):
        continue
    try:
        min_val = float(parts[3])
        max_val = float(parts[4])
    except ValueError:
        continue
    ranges[parts[0]] = (min_val, max_val)

# Conversion factors to US conventional units (multiply by factor)
conversion_factors = {
    'Serum_Creatinine': [0.0113],
    'BUN': [2.8],
    'Magnesium': [2.43, 1/0.823],
    'Serum_Calcium': [4.0, 2.0],
    'Ionized_Calcium': [0.25],
    'Phosphorus': [3.1],
    'Intact_PTH': [9.43],
    'Vitamin_D_25OH': [0.4],
    'Vitamin_D_1_25OH': [0.385],
    'Hemoglobin': [0.1, 1.611],
    'Hematocrit': [100.0],
    'Serum_Iron': [5.59],
    'TIBC': [5.59],
    'Ferritin': [1/2.247],
    'Total_Bilirubin': [0.058],
    'Direct_Bilirubin': [0.058],
    'Albumin_Serum': [0.1],
    'Total_Protein': [0.1],
    'Prealbumin': [0.1, 100.0],
    'CRP': [10.0],
    'Total_Cholesterol': [38.67],
    'LDL_Cholesterol': [38.67],
    'HDL_Cholesterol': [38.67],
    'Triglycerides': [88.5],
    'Non_HDL_Cholesterol': [38.67],
    'Glucose': [18.02],
    'Uric_Acid': [0.0168],
    'Urine_Albumin': [10.0],
    'Urine_Creatinine': [0.0113, 0.113],
    'Albumin_to_Creatinine_Ratio_Urine': [8.84],
    'Protein_to_Creatinine_Ratio_Urine': [8.84],
    'Urine_Protein': [0.1],
    'BNP': [3.46],
    'NT_proBNP': [8.47],
    'Troponin_I': [0.001],
    'Troponin_T': [0.001],
    'Free_T4': [0.078],
    'Free_T3': [0.651],
    'pCO2_Arterial': [7.5],
    'pO2_Arterial': [7.5],
    'Lactate': [0.111],
    'Aluminum': [26.98],
}

missing_tokens = {'', 'nan', 'none', 'null', 'na', 'n/a'}

def parse_value(value):
    if pd.isna(value):
        return np.nan
    s = str(value).strip()
    if s.lower() in missing_tokens:
        return np.nan

    s = s.replace(' ', '')

    if ',' in s and '.' in s:
        if s.rfind(',') > s.rfind('.'):
            s = s.replace('.', '')
            s = s.replace(',', '.')
        else:
            s = s.replace(',', '')
    elif ',' in s:
        s = s.replace(',', '.')

    try:
        return float(s)
    except ValueError:
        s2 = re.sub(r'[^0-9eE.+-]', '', s)
        if s2 == '' or s2.lower() in missing_tokens:
            return np.nan
        try:
            return float(s2)
        except ValueError:
            return np.nan


def within_tolerance(val, min_val, max_val, tol=0.05):
    if min_val == max_val:
        return abs(val - min_val) <= abs(min_val) * tol
    if val < min_val:
        if min_val == 0:
            return val >= -max_val * tol
        return val >= min_val * (1 - tol)
    if val > max_val:
        return val <= max_val * (1 + tol)
    return True


def clamp(val, min_val, max_val):
    if val < min_val:
        return min_val
    if val > max_val:
        return max_val
    return val


def convert_unit_if_needed(value, column):
    if pd.isna(value):
        return value
    if column not in ranges:
        return value

    min_val, max_val = ranges[column]

    if min_val <= value <= max_val:
        return value

    # HbA1c special handling (IFCC mmol/mol -> NGSP %)
    if column == 'HbA1c':
        converted = (value / 10.929) + 2.15
        if min_val <= converted <= max_val:
            return converted
        if within_tolerance(converted, min_val, max_val):
            return clamp(converted, min_val, max_val)

    for factor in conversion_factors.get(column, []):
        converted = value * factor
        if min_val <= converted <= max_val:
            return converted
        if within_tolerance(converted, min_val, max_val):
            return clamp(converted, min_val, max_val)

    return value

# Apply parsing
numeric_cols = [c for c in raw_df.columns if c != 'patient_id']

df = raw_df.copy()
for col in numeric_cols:
    df[col] = df[col].apply(parse_value)

# Drop rows with any missing values after parsing
before_rows = len(df)
df = df.dropna(subset=numeric_cols).reset_index(drop=True)
after_rows = len(df)

# Unit harmonization
for col in numeric_cols:
    df[col] = df[col].apply(lambda x: convert_unit_if_needed(x, col))

# Final clamp to keep within expected ranges (after conversion attempts)
for col in numeric_cols:
    if col in ranges:
        min_val, max_val = ranges[col]
        df[col] = df[col].clip(lower=min_val, upper=max_val)

# Format to 2 decimals
for col in numeric_cols:
    df[col] = df[col].apply(lambda x: f"{x:.2f}" if pd.notna(x) else '')

if 'patient_id' in df.columns:
    cols = ['patient_id'] + [c for c in df.columns if c != 'patient_id']
    df = df[cols]

df.to_csv(output_path, index=False)

print(f"Rows before: {before_rows}")
print(f"Rows after dropping missing: {after_rows}")
print(f"Saved: {output_path}")
PY"}

